changeSet.sql:
Create or Alter Procedure [dbo].[GenerateOwnerShipDataForGetAsset] @AssetTypeID int AS BEGIN SET NOCOUNT ON; if (OBJECT_ID('tempdb..#OwnershipLookupAssets') IS NOT NULL and OBJECT_ID('tempdb..#tempasset') IS NOT NULL) begin if exists(select 1 from #OwnershipLookupAssets) BEGIN drop table if exists #OwnershipLookupAssets_temp;
select * into #OwnershipLookupAssets_temp from ( select ow.* from #tempasset tempa inner join #OwnershipLookupAssets ow on tempa.AssetID = ow.AssetID union all select ow.* from #OwnershipLookupAssets ow where ow.AssetID = 0 )a ;
truncate table #OwnershipLookupAssets;
insert into #OwnershipLookupAssets select * from #OwnershipLookupAssets_temp;
drop table if exists #OwnershipLookupAssets_temp; end else BEGIN insert into #OwnershipLookupAssets select r.AssetID, r.ResponsibilityTypeID as ResponsibilityTypeID, r.ResponsibilityTypeName, r.ResourceName, case when r.SecurityType = 1 then 'G' else 'R' end SecurityAsset, case when r.SecurityType = 1 then r.GroupName else r.ResourceName end as SecurityAssetName, r.Context, r.ResourceID as ResourceID, r.ResourceUid as ResourceUid, r.SecurityId SecurityAssetID, case when r.SecurityType = 1 then r.GroupUid else r.ResourceUid end as SecurityAssetUid from #tempasset tempa inner join ResponsibilitySummary r on (r.AssetID = tempa.AssetID and r.IsVisible = 1) End end end
